#include <omp.h>
#include <vector>
#include <cstddef>

double productWithInverses(std::vector<double> const& x) {
    double product = 1.0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for default(none) shared(x, n) reduction(* : product)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const double term = (i % 2 == 0) ? x[static_cast<std::size_t>(i)]
                                         : 1.0 / x[static_cast<std::size_t>(i)];
        product *= term;
    }

    return product;
}
